const setDiscussionThreadState = `-- name: SetDiscussionThreadState :one
INSERT INTO conversation_thread_states(company_id,conversation_id,root_id,user_id,grant_generation,follow,read_seq)
VALUES($1::uuid,$2::uuid,$3::uuid,$4::uuid,
    $5::bigint,$6::text,$7::bigint)
ON CONFLICT(root_id,user_id) DO UPDATE SET updated_at=clock_timestamp(),grant_generation=EXCLUDED.grant_generation,follow=EXCLUDED.follow,
    manual_unread_seq=CASE WHEN conversation_thread_states.grant_generation=EXCLUDED.grant_generation THEN conversation_thread_states.manual_unread_seq END,
    read_seq=CASE WHEN conversation_thread_states.grant_generation<>EXCLUDED.grant_generation THEN EXCLUDED.read_seq ELSE conversation_thread_states.read_seq END,
    version=conversation_thread_states.version+1 RETURNING company_id, conversation_id, root_id, user_id, created_at, updated_at, grant_generation, follow, read_seq, version, unread_count, manual_unread_seq
`

type SetDiscussionThreadStateParams struct {
	CompanyID       uuid.UUID `json:"company_id"`
	ConversationID  uuid.UUID `json:"conversation_id"`
	RootID          uuid.UUID `json:"root_id"`
	UserID          uuid.UUID `json:"user_id"`
	GrantGeneration int64     `json:"grant_generation"`
	Follow          string    `json:"follow"`
	ReadSeq         int64     `json:"read_seq"`
}

// Explicit state CAS is checked by the service under the Conversation lock.
// A stale grant is invisible; its replacement keeps a monotonic stored version.
func (q *Queries) SetDiscussionThreadState(ctx context.Context, arg SetDiscussionThreadStateParams) (ConversationThreadState, error) {
	row := q.db.QueryRow(ctx, setDiscussionThreadState,
		arg.CompanyID,
		arg.ConversationID,
		arg.RootID,
		arg.UserID,
		arg.GrantGeneration,
		arg.Follow,
		arg.ReadSeq,
	)
	var i ConversationThreadState
	err := row.Scan(
		&i.CompanyID,
		&i.ConversationID,
		&i.RootID,
		&i.UserID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.GrantGeneration,
		&i.Follow,
		&i.ReadSeq,
		&i.Version,
		&i.UnreadCount,
		&i.ManualUnreadSeq,
	)
	return i, err
}

